'use strict';
const E=JourneyEngine,$=id=>document.getElementById(id),esc=E.escape;
let data,report,records=[],assets=[],role='Pastor',selected=null,journey=null,day=0,page=0,assetLimit=50,dirty=false;
const pageSize=18;
function notice(t){$('notice').textContent=t;}
function view(name){document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==name);document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-current',b.dataset.view===name?'page':'false'));history.replaceState(null,'','#'+name);}
function setRole(r){role=r;document.querySelectorAll('[data-role]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.role===r));if(!journey)$('focus').value=r==='Advisor'?'legacy':'formation';}
function saveFile(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function slug(){return (journey?.profile.title||'journey').replace(/[^a-z0-9]+/gi,'-').slice(0,70).replace(/^-|-$/g,'').toLowerCase()||'journey';}
function titleHeld(title){return records.some(r=>E.norm(r.title)===E.norm(title)&&E.restricted(r.original||{}));}
function filtered(){const q=E.norm($('search').value).split(' ').filter(Boolean),v=$('eligibility').value;return records.filter(r=>(v==='all'||(v==='reference'?r.blocked:!r.blocked))&&q.every(w=>r.search.includes(w)));}
function renderLibrary(){const list=filtered(),max=Math.max(1,Math.ceil(list.length/pageSize));page=Math.min(page,max-1);$('counts').textContent=list.length.toLocaleString()+' source placements';$('results').innerHTML=list.slice(page*pageSize,(page+1)*pageSize).map(r=>'<article class="card"><small>'+esc(r.category||'Uncategorized source')+'</small><h3>'+esc(r.title)+'</h3><p>'+esc(r.subtitle||'Subtitle not supplied in source')+'</p><div class="provenance">'+esc(r.id)+' · '+esc(r.reason)+'<br>'+esc(r.source)+'<br>'+esc(r.locator)+'</div><button data-record="'+esc(r.key)+'" '+(r.blocked?'disabled':'')+'>'+(r.blocked?'Reference / held':'Build this journey →')+'</button></article>').join('')||'<p>No matches. Try a shorter search or show all source placements.</p>';$('page-info').textContent='Page '+(page+1)+' of '+max;$('previous').disabled=page===0;$('next').disabled=page>=max-1;}
function selectRecord(r){selected=r;$('title').value=r?.title||'';$('subtitle').value=r?.subtitle||'';const t=E.norm([r?.title,r?.category,r?.audience].join(' '));$('focus').value=/generos|steward|giving|financ/.test(t)?'generosity':/legacy|family|parent|heir/.test(t)?'legacy':/peace|anxiety|rest|resilien/.test(t)?'peace':/leader|business|purpose|work/.test(t)?'leadership':/belong|community|group|relationship/.test(t)?'community':role==='Advisor'?'legacy':'formation';$('source-info').textContent=r?r.id+' · '+r.source+' · '+r.locator+' · Source wording preserved; devotional text will be a new draft.':'Custom title · Original LifeTogether devotional framework';view('builder');$('title').focus();}
function profile(){return{title:$('title').value.trim(),subtitle:$('subtitle').value.trim(),prepared:$('prepared').value.trim(),duration:Number($('duration').value),focus:$('focus').value,role,date:$('start-date').value,notes:$('notes').value,sourceId:selected?.id||'',sourceTitle:selected?.title||'',sourceSubtitle:selected?.subtitle||'',source:selected?[selected.source,selected.locator].filter(Boolean).join(' · '):''};}
function populate(p){for(const k of ['title','subtitle','prepared','duration','focus','notes'])$(k).value=p[k]||'';$('start-date').value=p.date||'';setRole(p.role);$('focus').value=p.focus;selected=p.sourceId?{id:p.sourceId,title:p.sourceTitle,subtitle:p.sourceSubtitle,source:p.source,locator:''}:null;$('source-info').textContent=p.sourceId?p.sourceId+' · '+p.source:'Custom title';}
function edited(){dirty=true;$('saved-state').textContent='Unsaved changes in this tab. Save journey to keep your edits.';}
function editor(){if(!journey)return;$('workbook').hidden=false;$('workbook-title').textContent=journey.profile.title+' · '+journey.days.length+' days';$('day-select').innerHTML=journey.days.map((d,i)=>'<option value="'+i+'">Day '+d.number+' · '+esc(d.title)+'</option>').join('');$('day-select').value=day;$('day-list').innerHTML=journey.days.map((d,i)=>'<button data-day="'+i+'" aria-current="'+(i===day)+'">'+(d.reviewed?'✓ ':'')+d.number+'. '+esc(d.title)+'</button>').join('');const d=journey.days[day];$('day-editor').innerHTML='<div class="day-heading"><p class="eyebrow">DAY '+d.number+' OF '+journey.days.length+'</p><span class="badge">EDITABLE DRAFT</span></div>'+Object.entries(E.fields).map(([k,l])=>'<label>'+l+(k==='title'||k==='scripture'?'<input data-field="'+k+'" value="'+esc(d[k])+'" maxlength="20000">':'<textarea data-field="'+k+'" rows="'+(k==='teaching'?8:k==='scene'||k==='questions'?4:3)+'" maxlength="20000">'+esc(d[k])+'</textarea>')+'</label>').join('')+'<label><input type="checkbox" id="reviewed" '+(d.reviewed?'checked':'')+' style="display:inline;width:auto"> I have reviewed this day’s wording and Scripture fit.</label>';$('session-preview').innerHTML='<p class="eyebrow">CONTINUE THE CONVERSATION</p><h2>Group & family conversations</h2>'+E.sessions(journey).map(s=>'<details><summary>Conversation '+s.number+' · '+s.range+' · '+esc(s.title)+'</summary><p style="white-space:pre-wrap">'+esc(s.body)+'</p></details>').join('');}
function renderAssets(){if(!report)return;const q=E.norm($('asset-search').value).split(' ').filter(Boolean),type=$('asset-type').value,list=assets.filter(a=>(!type||a.format===type)&&q.every(w=>a.search.includes(w)));$('assets').innerHTML=list.slice(0,assetLimit).map(a=>{const url='https://github.com/BRETTLIFETOGETHER/claude-artifacts/blob/'+report.archiveCommit+'/'+a.path.split('/').map(encodeURIComponent).join('/');return'<article class="asset"><div><b>'+esc(a.name)+'</b><small>'+esc(a.id)+' · '+esc(a.format)+'</small></div><div><b>'+esc(a.project)+'</b><p>'+esc(a.description||'No source description supplied.')+'</p><small>Git blob '+esc(a.sha)+'</small></div><a href="'+url+'" target="_blank" rel="noopener">Open source ↗</a></article>';}).join('')||'<p>No matching source files.</p>';$('more-assets').hidden=assetLimit>=list.length;$('more-assets').textContent='Show 50 more · '+list.length+' matches';}
function backup(){saveFile(slug()+'.journey.json',JSON.stringify(journey,null,2),'application/json');dirty=false;$('saved-state').textContent='Journey backup downloaded. Keep it to reopen your work.';}
function guarded(action){try{if(!journey)throw Error('Build a journey first.');if(titleHeld(journey.profile.sourceTitle||journey.profile.title))throw Error('This source has a hold or reference restriction. Use the recovery index to review it.');action();}catch(e){notice(e.message);}}
async function load(){try{report=await fetch('recovery-report.json').then(r=>{if(!r.ok)throw Error('Recovery report is unavailable.');return r.json();});const url='https://raw.githubusercontent.com/BRETTLIFETOGETHER/Lifetogether-master-library/'+report.masterInputCommit+'/dist/data.js';let text;try{const r=await fetch('../data.js');if(!r.ok)throw Error();text=await r.text();if(!text.startsWith('window.LT_PAYLOAD'))throw Error();}catch{text=await fetch(url).then(r=>{if(!r.ok)throw Error('Master catalog is temporarily unavailable. Please reload.');return r.text();});}const sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),x=>x.toString(16).padStart(2,'0')).join('');if(sha!==report.inputPayloadSHA256){text=await fetch(url).then(r=>r.text());const s=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),x=>x.toString(16).padStart(2,'0')).join('');if(s!==report.inputPayloadSHA256)throw Error('Catalog verification changed. A refreshed recovery audit is required.');}const match=text.match(/window\.LT_PAYLOAD\s*=\s*"([A-Za-z0-9+/=]+)"/);if(!match)throw Error('Master catalog format is invalid.');const bytes=Uint8Array.from(atob(match[1]),c=>c.charCodeAt(0)),stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));data=JSON.parse(await new Response(stream).text());records=E.records(data).map((r,i)=>({...r,key:String(i),search:E.norm([r.title,r.subtitle,r.category,r.source,r.id,r.audience].join(' '))}));assets=data.assets.map(a=>({...a,search:E.norm([a.name,a.project,a.description].join(' '))}));$('asset-type').innerHTML='<option value="">All formats</option>'+[...new Set(assets.map(a=>a.format))].sort().map(x=>'<option>'+esc(x)+'</option>').join('');$('audit').innerHTML='<div><strong>'+report.hashMatchedFiles.toLocaleString()+'</strong><span>Original files verified by hash</span></div><div><strong>'+report.collections+'</strong><span>Recovered collections</span></div><div><strong>'+report.masterTitlesWithSubtitles.toLocaleString()+'</strong><span>Main catalog entries with subtitles</span></div>';$('footer-stats').textContent='Audit: '+report.checkedOn+' · '+report.indexedFiles+' original files';notice('Library verified · '+report.indexedFiles+' original archive files · 21-, 30-, and 40-day drafts available.');renderLibrary();renderAssets();}catch(e){notice(e.message+' You can still start with your own title.');$('results').textContent='Catalog could not be loaded. Refresh to retry.';}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)view(b.dataset.view);if(b.dataset.role)setRole(b.dataset.role);if(b.dataset.record!==undefined)selectRecord(records.find(r=>r.key===b.dataset.record));if(b.dataset.day!==undefined){day=Number(b.dataset.day);editor();}});
$('custom').onclick=()=>selectRecord(null);$('search').oninput=()=>{page=0;renderLibrary();};$('eligibility').onchange=()=>{page=0;renderLibrary();};$('previous').onclick=()=>{page--;renderLibrary();};$('next').onclick=()=>{page++;renderLibrary();};$('setup').onsubmit=e=>{e.preventDefault();try{const p=profile();if(selected?.blocked||titleHeld(p.sourceTitle||p.title))throw Error('This title has a source restriction. Choose another title or inspect the original source.');if(journey&&!confirm('Build a new draft? Download Save journey first if you want to keep the current daily edits.'))return;journey=E.build(p);day=0;editor();edited();notice('Your '+p.duration+'-day draft is ready to edit. Print includes every day and the conversation guides.');$('workbook').scrollIntoView({behavior:'smooth'});}catch(e){notice(e.message);}};
$('day-select').onchange=()=>{day=Number($('day-select').value);editor();};$('day-editor').addEventListener('input',e=>{const k=e.target.dataset.field;if(k){journey.days[day][k]=e.target.value;journey.days[day].reviewed=false;const checkbox=$('reviewed');if(checkbox)checkbox.checked=false;edited();}if(e.target.id==='reviewed'){journey.days[day].reviewed=e.target.checked;edited();}});
$('backup').onclick=()=>guarded(backup);$('markdown').onclick=()=>guarded(()=>saveFile(slug()+'.md',E.markdown(journey),'text/markdown'));$('html-download').onclick=()=>guarded(()=>saveFile(slug()+'-print.html',E.html(journey),'text/html'));$('print').onclick=()=>guarded(()=>{const win=window.open('','_blank');if(!win){notice('Allow a new tab for the print edition, or use Download print edition.');return;}win.opener=null;win.document.open();win.document.write(E.html(journey));win.document.close();win.focus();});
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>4000000)throw Error('Choose a backup smaller than 4 MB.');const next=E.validate(JSON.parse(await file.text()));if(titleHeld(next.profile.sourceTitle||next.profile.title))throw Error('This source is currently held or reference-only.');if(dirty&&!confirm('Replace the unsaved journey with this backup?'))return;journey=next;populate(next.profile);day=0;editor();dirty=false;$('saved-state').textContent='Backup opened. New edits remain in this tab until downloaded.';notice('Journey restored: '+next.days.length+' days.');}catch(e){notice(e.message);}finally{e.target.value='';}};
$('asset-search').oninput=$('asset-type').onchange=()=>{assetLimit=50;renderAssets();};$('more-assets').onclick=()=>{assetLimit+=50;renderAssets();};$('recovery-download').onclick=()=>{if(!data){notice('Wait for the recovery index to load.');return;}saveFile('lifetogether-master-recovery-index.json',JSON.stringify({verification:report,assets:data.assets},null,2),'application/json');};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});view(['library','builder','recovery'].includes(location.hash.slice(1))?location.hash.slice(1):'library');load();
